use vstd::prelude::*;

verus! {

fn get_first_elements(lst: Vec<Vec<i32>>) -> (result: Vec<i32>)
    requires
        // Every inner vector is non-empty
        forall|i: int| 0 <= i < lst.len() ==> lst[i].len() > 0,
    ensures
        // Output length equals input (outer) length
        result.len() == lst.len(),
        // Each output element is the first element of the corresponding inner vector
        forall|i: int| 0 <= i < lst.len() ==> result[i] == lst[i][0],
{
    let n: usize = lst.len();
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == lst.len(),
            i <= n,
            result.len() == i,
            // We keep the mapping correct for all indices already produced
            forall|k: int| 0 <= k < i ==> result[k] == lst[k][0],
            // Carry the precondition through the loop (useful to justify indexing)
            forall|k: int| 0 <= k < lst.len() ==> lst[k].len() > 0,
        decreases n - i,
    {
        // By the precondition, lst[i] is non-empty, so lst[i][0] is safe.
        let first: i32 = lst[i][0];
        result.push(first);
        i = i + 1;
    }

    result
}

} // verus!

